contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // param amount is the Ether to send to C; must be provided by caller
    // param fakeBlockTime and fakeBlockNum are not used (can't control block), kept out
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read pre-state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // perform the call that may revert: fallback requires msg.value == 10 ether
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule to assert for all inputs:
        // - If the call reverted then no observable change in c's public state or balance.
        // - If the call succeeded and amount == 10 ether, then pastBlockTime is updated to current block.timestamp
        //   (i.e., strictly greater than beforePast) and either C paid out its entire balance to this contract iff block.number % 15 == 0,
        //   otherwise the contract's balance increased by amount and pastBlockTime updated.
        // Implement as a single boolean assertion combining these cases.

        bool noChangeOnRevert = reverted ? (afterPast == beforePast && afterBal == beforeBal) : true;

        bool successCase = true;
        if (!reverted) {
            // call succeeded
            // If amount != 10 ether, fallback would have reverted; so here amount == 10 ether must hold.
            // Assert that pastBlockTime was increased to current block.timestamp (>= before and > before if block.timestamp strictly increases)
            // We assert it is >= beforePast and equal to block.timestamp (observable getter gives stored value), but block.timestamp is accessible.
            bool pastUpdated = (afterPast == block.timestamp) && (afterPast >= beforePast);

            // payout condition: if block.number % 15 == 0 then C should have transferred its entire balance away to this contract
            if (block.number % 15 == 0) {
                // After payout, c's balance should be zero (since payable(msg.sender).transfer(address(this).balance) drains it)
                successCase = (afterBal == 0) && (address(this).balance >= amount);
            } else {
                // Otherwise, contract should keep the sent amount, so its balance increases by amount
                successCase = (afterBal == beforeBal + amount);
            }
            successCase = successCase && pastUpdated;
        }

        assert(noChangeOnRevert && successCase);
    }

    // allow this test contract to receive ETH when C transfers out
    receive() external payable {}
}

