contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept as inputs: amount to send and a simulated current block timestamp
    // (timestamp can't be set here; we only observe c.pastBlockTime and block.timestamp implicitly),
    // but to drive Ether transfer behavior we need to send exactly 10 ether or another amount.
    // The test will call the fallback by sending amount.

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");
        // Read the observable before-state
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        // Make the deciding call to fallback by sending Ether; fallback requires msg.value == 10 ether
        // so for amount != 10 ether it should revert because of the first require in fallback.
        // We capture whether it reverted.
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule to assert:
        // - If the call reverted then C's pastBlockTime and balance must be unchanged.
        // - If the call did not revert then pastBlockTime increased strictly to current block.timestamp
        //   (so afterPast > beforePast), and the only allowed balance decrease is to 0, which happens
        //   only if block.number % 15 == 0 (in which case the contract transfers all balance to msg.sender).
        // We cannot read block.number inside the assert, but we can assert the implication form:
        //   reverted -> (afterPast == beforePast && afterBal == beforeBal)
        //   !reverted -> (afterPast > beforePast && (afterBal == beforeBal || afterBal == 0))
        // This captures the intended invariant observable from outside.

        assert(
            (reverted && afterPast == beforePast && afterBal == beforeBal) ||
            (!reverted && afterPast > beforePast && (afterBal == beforeBal || afterBal == 0))
        );
    }

    // Allow receiving Ether so that this contract can hold balance to forward to c.
    receive() external payable {}

    // Minimal fallback to accept transfer from C when it drains funds.
    fallback() external payable {}
}

