        uint beforeBalanceThis = address(this).balance;

        // Perform the state-changing call: send amount to fallback
        bool reverted;
        // call fallback: msg.sender will be this contract
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterPast = c.pastBlockTime();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // General rule (single assert):
        // - If the call reverted then nothing observable on c changed (pastBlockTime and balance remain same)
